const els = Object.fromEntries(['player-title','player-artist','player-like','player-cover','toggle-play','current-time','duration','seek-bar','volume-bar','shuffle-button','repeat-button','full-title','full-artist','full-like','full-cover','full-toggle-play','full-current-time','full-duration','full-seek','full-shuffle','full-repeat','now-playing-screen','recent-list','recent-history-list','recent-history-empty','artist-page-art','artist-page-title','artist-page-count','artist-page-play','artist-track-list','artist-track-empty','liked-preview','recommendation-list','library-list','liked-list','community-home-heading','community-home-list','community-library-heading','community-library-list','community-count','community-empty','folder-grid','folder-section-title','songs-section-title','show-all-folders','library-empty','liked-empty','home-empty','library-total','liked-total','liked-subtitle','library-count','liked-count','search-input','search-results','toast','install-button','queue-dialog','queue-list','queue-empty','admin-dialog','admin-folder-link','admin-account-create','cloud-status','cloud-retry','admin-login-form','admin-upload-form','upload-submit','create-uploader-button','playlist-grid','playlist-detail','playlist-detail-heading','playlist-detail-count','playlist-detail-list','playlist-add-picker','liked-add-picker','liked-add-toggle','track-actions-dialog','track-actions-title','track-actions-subtitle','track-actions-main','track-remove-from-list','track-add-to-other','track-playlist-chooser','track-playlist-options','track-action-create-form','track-action-new-playlist-name','delete-playlist-dialog','delete-playlist-name','delete-playlist-countdown','delete-playlist-status','delete-playlist-confirm','delete-playlist-cancel','create-playlist-dialog','create-playlist-form','profile-display-name','profile-avatar-file','profile-save-button','profile-edit-form'].map(id=>[id,document.getElementById(id)]));

function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('tracks'))db.createObjectStore('tracks',{keyPath:'id'});if(!db.objectStoreNames.contains('playlists'))db.createObjectStore('playlists',{keyPath:'id'});if(!db.objectStoreNames.contains('downloads'))db.createObjectStore('downloads',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbRequest(mode,callback,storeName='tracks'){return new Promise((resolve,reject)=>{const tx=state.db.transaction(storeName,mode);const store=tx.objectStore(storeName);let req;try{req=callback(store);}catch(e){reject(e);return;}tx.oncomplete=()=>resolve(req?.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
const putTrack=t=>dbRequest('readwrite',s=>s.put(t));
const deleteTrack=id=>dbRequest('readwrite',s=>s.delete(id));
const getTracks=()=>dbRequest('readonly',s=>s.getAll());
const putPlaylist=playlist=>dbRequest('readwrite',s=>s.put(playlist),'playlists');
const getAllPlaylists=()=>dbRequest('readonly',s=>s.getAll(),'playlists');
const deletePlaylistRecord=playlistId=>dbRequest('readwrite',s=>s.delete(playlistId),'playlists');
const putDownload=track=>dbRequest('readwrite',s=>s.put(track),'downloads');
const getDownloads=()=>dbRequest('readonly',s=>s.getAll(),'downloads');
const deleteDownload=trackId=>dbRequest('readwrite',s=>s.delete(trackId),'downloads');

function id(){return crypto.randomUUID?.()??`${Date.now()}-${Math.random().toString(36).slice(2)}`;}
function formatTime(seconds){if(!Number.isFinite(seconds)||seconds<0)return '0:00';const m=Math.floor(seconds/60),s=Math.floor(seconds%60);return `${m}:${String(s).padStart(2,'0')}`;}
function escapeHTML(value=''){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(message,duration=2500){els.toast.textContent=message;els.toast.classList.add('show');clearTimeout(state.toastTimer);if(duration>0)state.toastTimer=setTimeout(()=>els.toast.classList.remove('show'),duration);}
function artistFromFile(name){return name.includes(' - ')?name.split(' - ')[0].trim():'Từ thiết bị của bạn';}
function titleFromFile(name){const base=name.replace(/\.[^.]+$/,'');return base.includes(' - ')?base.split(' - ').slice(1).join(' - ').trim():base;}
function trackById(trackId){return state.downloads.find(t=>t.id===trackId)||state.tracks.find(t=>t.id===trackId)||state.sharedTracks.find(t=>t.id===trackId);}
function allTracks(){const ids=[...new Set([...state.sharedTracks,...state.tracks,...state.downloads].map(track=>track.id))];return ids.map(trackById).filter(Boolean);}
function isDownloaded(track){return !!track&&(!!track.blob||state.downloads.some(item=>item.id===track.id)||state.tracks.some(item=>item.id===track.id&&!!item.blob));}
async function downloadTrack(trackId,{silent=false}={}){
  if(isDownloaded(trackById(trackId)))return 'already';
  if(state.downloadJobs.has(trackId))return state.downloadJobs.get(trackId);
  const source=state.sharedTracks.find(track=>track.id===trackId);
  if(!source?.audioUrl)throw new Error('Bài hát này không có tệp tải xuống.');
  if(!silent)toast(`Đang tải “${source.title}”…`,60000);
  const job=(async()=>{
    try{
      const response=await fetch(source.audioUrl);
      if(!response.ok)throw new Error(`Máy chủ trả về lỗi ${response.status}.`);
      const blob=await response.blob();
      if(!blob.size)throw new Error('Tệp nhạc tải về đang trống.');
      const downloaded={...source,blob,isDownloaded:true,downloadedAt:Date.now()};
      await putDownload(downloaded);
      state.downloads.push(downloaded);
      render();
      if(!silent)toast(`Đã tải “${source.title}” để nghe ngoại tuyến.`);
      return 'downloaded';
    }catch(error){
      if(!silent)toast(`Không tải được bài hát: ${error.message||'lỗi kết nối hoặc thiếu dung lượng'}.`);
      throw error;
    }finally{state.downloadJobs.delete(trackId);}
  })();
  state.downloadJobs.set(trackId,job);
  return job;
}
async function downloadPlaylist(playlistId){
  const playlist=state.playlists.find(item=>item.id===playlistId);
  if(!playlist)return;
  const tracks=(playlist.trackIds||[]).map(trackById).filter(Boolean);
  const pending=tracks.filter(track=>track.isShared&&!isDownloaded(track));
  const skipped=tracks.length-pending.length;
  if(!pending.length){toast(tracks.length?'Danh sách này đã có thể nghe ngoại tuyến.':'Danh sách phát chưa có bài hát.');return;}
  let downloaded=0,failed=0;
  for(let index=0;index<pending.length;index++){
    const track=pending[index];
    toast(`Đang tải ${index+1}/${pending.length}: ${track.title}`,60000);
    try{if(await downloadTrack(track.id,{silent:true})==='downloaded')downloaded++;}
    catch{failed++;}
  }
  render();
  const summary=`Đã tải ${downloaded} bài${skipped?`, bỏ qua ${skipped} bài đã có sẵn`:''}${failed?`, ${failed} bài gặp lỗi`:''}.`;
  toast(summary,5000);
}
async function removeDownloadedTrack(trackId){
  const track=state.downloads.find(item=>item.id===trackId);
  if(!track)return;
  await deleteDownload(trackId);
  state.downloads=state.downloads.filter(item=>item.id!==trackId);
  render();
  toast(`Đã xóa “${track.title}” khỏi danh sách tải xuống.`);
}
function playPlaylist(playlistId){
  const playlist=state.playlists.find(item=>item.id===playlistId);
  const tracks=(playlist?.trackIds||[]).map(trackById).filter(Boolean);
  state.selectedPlaylistId=playlistId;
  renderPlaylists();
  if(tracks.length)playTrack(tracks[0].id,tracks);
  else toast('Danh sách phát chưa có bài hát.');
}
function recentlyPlayedTracks(){return state.playHistory.map(trackById).filter(Boolean);}
function artistKey(name){return String(name||'').normalize('NFC').trim().replace(/\s+/g,' ').toLocaleLowerCase('vi');}
function artistTracks(name=state.selectedArtist){const key=artistKey(name);return allTracks().filter(track=>artistKey(track.artist)===key);}
function likedTracks(){return allTracks().filter(t=>t.liked);}
function playlistOwnerId(){return state.user?.id||'guest';}
function historyStorageKey(){return `pink-tune-play-history:${playlistOwnerId()}`;}
function parseStoredArray(key){try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value:[];}catch{return [];}}
function recommendationTracks(){const tracks=allTracks();if(!tracks.length)return [];const likes=likedTracks();const affinity=new Map();likes.forEach(t=>{const key=(t.artist||'').trim().toLocaleLowerCase('vi');if(key)affinity.set(key,(affinity.get(key)||0)+5);});state.playHistory.slice(0,24).forEach((trackId,index)=>{const t=trackById(trackId);const key=(t?.artist||'').trim().toLocaleLowerCase('vi');if(key)affinity.set(key,(affinity.get(key)||0)+Math.max(1,4-index*.12));});return tracks.map((track,index)=>({track,index,score:(affinity.get((track.artist||'').trim().toLocaleLowerCase('vi'))||0)+(track.liked?2:0)+(track.isShared?0.25:0)})).sort((a,b)=>b.score-a.score||(Date.parse(b.track.createdAt||'')||b.track.addedAt||0)-(Date.parse(a.track.createdAt||'')||a.track.addedAt||0)||a.index-b.index).map(item=>item.track);}
async function loadPlaylists(){const all=await getAllPlaylists();state.playlists=all.filter(playlist=>(playlist.ownerId||'guest')===playlistOwnerId());renderPlaylists();}
function renderProfile(){const user=state.user;const email=user?.email||'';const fallbackName=email?email.split('@')[0]:'Người nghe Pink Tune';const name=state.profile.displayName||fallbackName;const initials=(name||'PT').trim().slice(0,2).toUpperCase();const role=state.admin?'Quản trị viên':state.canUpload?'Tài khoản thường':user?'Người nghe':'Khách';const note=state.admin?'Bạn có quyền đăng nhạc, tạo tài khoản thường và mở công cụ quản trị.':state.canUpload?'Tài khoản thường có thể đăng nhạc lên thư viện cộng đồng. Quyền quản trị và Table Editor chỉ dành cho admin.':user?'Tài khoản này hiện có quyền nghe nhạc và lưu thư viện cá nhân.':'Bạn có thể nghe nhạc và lưu thư viện riêng trên thiết bị. Đăng nhập để dùng quyền tài khoản của mình.';const button=document.getElementById('profile-button');const buttonInitials=document.getElementById('profile-button-initials');const buttonImage=document.getElementById('profile-button-image');buttonInitials.textContent=initials;buttonImage.hidden=!state.profile.avatarUrl;if(state.profile.avatarUrl)buttonImage.src=state.profile.avatarUrl;button.setAttribute('aria-label',`Trang cá nhân, ${role}`);document.getElementById('profile-large-avatar-initials').textContent=initials;const largeImage=document.getElementById('profile-large-avatar-image');largeImage.hidden=!state.profile.avatarUrl;if(state.profile.avatarUrl)largeImage.src=state.profile.avatarUrl;document.getElementById('profile-name').textContent=state.admin?'Quản trị viên':name;document.getElementById('profile-email').textContent=email||(state.accountReady?'Chưa đăng nhập':'Đang kiểm tra tài khoản…');document.getElementById('profile-role').textContent=role;document.getElementById('profile-permission-note').textContent=note;document.getElementById('profile-local-count').textContent=state.tracks.length;document.getElementById('profile-liked-count').textContent=likedTracks().length;const loginButton=document.getElementById('profile-login');loginButton.hidden=!!user;loginButton.disabled=!state.accountReady||!state.supabase;loginButton.textContent=state.supabase?'Đăng nhập tài khoản':'Đăng nhập chưa khả dụng';document.getElementById('profile-upload').hidden=!state.canUpload;document.getElementById('profile-signout').hidden=!user;document.getElementById('profile-admin-tools').hidden=!state.admin;document.getElementById('profile-edit-form').hidden=!user;document.getElementById('settings-login-note').hidden=!!user;if(user&&els['profile-display-name'])els['profile-display-name'].value=state.profile.displayName||fallbackName;}

async function importFiles(files){const audioFiles=[...files].filter(f=>f.type.startsWith('audio/')||/\.(mp3|m4a|aac|wav|ogg|opus|flac)$/i.test(f.name));if(!audioFiles.length){toast('Không tìm thấy tệp âm thanh phù hợp.');return;}let added=0;for(const file of audioFiles){const relativePath=file.webkitRelativePath||'';const folder=relativePath?relativePath.split('/')[0]:'Nhạc của tôi';const track={id:id(),name:file.name,title:titleFromFile(file.name),artist:artistFromFile(file.name),folder,size:file.size,type:file.type,addedAt:Date.now()+added,liked:false,blob:file};try{await putTrack(track);state.tracks.push(track);added++;}catch{toast('Không đủ dung lượng để lưu thêm nhạc.');break;}}fileInput.value='';folderInput.value='';render();toast(`Đã thêm ${added} bài hát vào thư viện.`);if(added&&state.tracks.length===added)playTrack(state.tracks[0].id);}

function currentCollection(){return state.queue.length?state.queue:state.tracks;}
function playTrack(trackId,collection){const t=trackById(trackId);if(!t)return;if(collection)state.queue=collection.map(x=>typeof x==='string'?x:x.id);else if(!state.queue.includes(trackId))state.queue=allTracks().map(x=>x.id);state.queueIndex=state.queue.indexOf(trackId);state.currentId=trackId;state.playHistory=[trackId,...state.playHistory.filter(x=>x!==trackId)].slice(0,60);localStorage.setItem(historyStorageKey(),JSON.stringify(state.playHistory));if(state.objectUrl){URL.revokeObjectURL(state.objectUrl);state.objectUrl=null;}if(t.blob){state.objectUrl=URL.createObjectURL(t.blob);audio.src=state.objectUrl;}else audio.src=t.audioUrl;audio.load();audio.play().then(()=>{updatePlayer();render();}).catch(()=>{updatePlayer();render();toast('Chạm nút phát để bắt đầu nghe.');});}
function togglePlay(){if(!state.currentId){const first=allTracks()[0];if(first)playTrack(first.id);else{openPicker();toast('Thêm nhạc từ điện thoại để bắt đầu.');}return;}if(audio.paused)audio.play().catch(()=>toast('Không thể phát tệp này trên trình duyệt.'));else audio.pause();updatePlayer();}
function nextTrack(){const list=state.queue.length?state.queue:allTracks();if(!list.length)return;if(state.repeat==='one'){audio.currentTime=0;audio.play();return;}let next;if(state.shuffle&&list.length>1){do{next=Math.floor(Math.random()*list.length);}while(next===state.queueIndex);}else next=(state.queueIndex+1)%list.length;if(state.repeat==='off'&&state.queueIndex===list.length-1){audio.pause();audio.currentTime=0;updatePlayer();return;}state.queueIndex=next;playTrack(list[next]);}
function previousTrack(){if(audio.currentTime>3){audio.currentTime=0;return;}const list=state.queue.length?state.queue:allTracks();if(!list.length)return;state.queueIndex=(state.queueIndex-1+list.length)%list.length;playTrack(list[state.queueIndex]);}
function updatePlayer(){const t=trackById(state.currentId);const title=t?.title||'Chưa phát nhạc';const artist=t?.artist||'Thêm nhạc từ thiết bị để bắt đầu';const like=t?.liked?'♥':'♡';const playing=!audio.paused;els['toggle-play'].textContent=playing?'Ⅱ':'▶';els['toggle-play'].setAttribute('aria-label',playing?'Tạm dừng':'Phát nhạc');els['full-toggle-play'].textContent=playing?'Ⅱ':'▶';els['full-toggle-play'].setAttribute('aria-label',playing?'Tạm dừng':'Phát nhạc');document.querySelector('.player-bar')?.classList.toggle('is-playing',playing);els['now-playing-screen'].classList.toggle('is-playing',playing);els['player-title'].textContent=title;els['player-artist'].textContent=artist;els['full-title'].textContent=title;els['full-artist'].textContent=artist;els['player-like'].textContent=like;els['full-like'].textContent=like;els['player-like'].classList.toggle('liked',!!t?.liked);els['full-like'].classList.toggle('liked',!!t?.liked);document.title=t?`${t.title} — Pink Tune`:'Pink Tune — Your music';renderPlayerArtwork(t);if(t&&'mediaSession'in navigator){const artwork=t.coverUrl?[{src:t.coverUrl,sizes:'512x512'}]:[];navigator.mediaSession.metadata=new MediaMetadata({title:t.title,artist:t.artist,album:'Pink Tune',artwork});navigator.mediaSession.playbackState=playing?'playing':'paused';}els['shuffle-button']?.classList.toggle('active',state.shuffle);els['full-shuffle']?.classList.toggle('active',state.shuffle);els['shuffle-button']?.setAttribute('aria-pressed',String(state.shuffle));els['full-shuffle']?.setAttribute('aria-pressed',String(state.shuffle));els['repeat-button']?.classList.toggle('active',state.repeat!=='off');els['full-repeat']?.classList.toggle('active',state.repeat!=='off');els['repeat-button']?.setAttribute('aria-pressed',String(state.repeat!=='off'));els['full-repeat']?.setAttribute('aria-pressed',String(state.repeat!=='off'));els['repeat-button'].textContent=state.repeat==='one'?'↻₁':'↻';els['full-repeat'].textContent=state.repeat==='one'?'↻₁':'↻';if(t){els['player-cover'].setAttribute('data-track',t.id);els['full-cover'].setAttribute('data-track',t.id);}}
function renderPlayerArtwork(track){for(const [imageId,url] of [['player-cover-image',track?.coverUrl],['full-cover-image',track?.coverUrl]]){const image=document.getElementById(imageId);if(!image)continue;image.hidden=!url;if(url)image.src=url;}els['full-cover'].classList.toggle('has-image',!!track?.coverUrl);}

function trackRow(t,index,options={}){
  const playing=state.currentId===t.id;
  const source=options.album??(t.isShared?'Pink Tune':'Tệp trên thiết bị');
  const removeButton=options.collectionActions?'':options.downloadList?`<button class="icon-action" data-download-remove="${escapeHTML(t.id)}" aria-label="Xóa khỏi danh sách tải xuống">×</button>`:options.playlistId?`<button class="icon-action" data-playlist-remove="${escapeHTML(options.playlistId)}" data-track-id="${escapeHTML(t.id)}" aria-label="Xóa khỏi danh sách phát">−</button>`:t.isShared?'':`<button class="icon-action" data-remove="${escapeHTML(t.id)}" aria-label="Xóa khỏi thư viện">×</button>`;
  const indicator=playing&&!audio.paused?'<span class="equalizer" aria-label="Đang phát"><i></i><i></i><i></i></span>':String(index+1).padStart(2,'0');
  const cover=t.coverUrl?`<img src="${escapeHTML(t.coverUrl)}" alt="" loading="lazy">`:'♫';
  const owner=t.isShared&&t.uploaderName?`<span class="track-owner">${t.uploaderAvatarUrl?`<img src="${escapeHTML(t.uploaderAvatarUrl)}" alt="" loading="lazy">`:''}<span>Đăng bởi ${escapeHTML(t.uploaderName)}</span></span>`:'';
  const downloadButton=t.isShared&&!options.downloadList?(isDownloaded(t)?`<button class="icon-action downloaded-action" type="button" aria-label="Đã tải xuống để nghe ngoại tuyến" title="Đã tải xuống" disabled>✓</button>`:`<button class="icon-action" type="button" data-download="${escapeHTML(t.id)}" aria-label="Tải xuống để nghe ngoại tuyến" title="Tải xuống">↓</button>`):'';
  const actionData=options.collectionActions?' data-long-press-actions="true"':'';
  const actionsButton=options.collectionActions?`<button class="icon-action track-more-action" type="button" data-track-actions="${escapeHTML(t.id)}" aria-label="Tùy chọn ${escapeHTML(t.title)}" title="Tùy chọn bài hát">⋮</button>`:'';
  return `<div class="track-row${playing?' playing':''}" data-track-row="${escapeHTML(t.id)}"${actionData}><span class="track-number">${indicator}</span><span class="track-cover">${cover}</span><span class="track-title"><b>${escapeHTML(t.title)}</b><button class="artist-link" type="button" data-artist="${escapeHTML(t.artist)}" aria-label="Mở trang nghệ sĩ ${escapeHTML(t.artist)}">${escapeHTML(t.artist)}</button>${owner}</span><span class="track-album">${escapeHTML(source)}</span><span class="track-duration">${escapeHTML(t.duration||'—:—')}</span><span class="row-actions"><button class="icon-action${t.liked?' liked':''}" data-like="${escapeHTML(t.id)}" aria-label="${t.liked?'Bỏ thích':'Thích'}">${t.liked?'♥':'♡'}</button>${downloadButton}${removeButton}${actionsButton}</span></div>`;
}
function renderList(node,items,options={}){
  node.innerHTML=items.map((t,i)=>trackRow(t,i,options)).join('');
  node.querySelectorAll('[data-track-row]').forEach(row=>{
    let holdTimer=null,suppressClick=false,suppressTimer=null,startX=0,startY=0;
    const clearHold=()=>{clearTimeout(holdTimer);holdTimer=null;};
    row.addEventListener('pointerdown',event=>{if(!options.collectionActions||event.target.closest('button,a,input')||(event.pointerType==='mouse'&&event.button!==0))return;startX=event.clientX;startY=event.clientY;clearHold();holdTimer=setTimeout(()=>{suppressClick=true;suppressTimer=setTimeout(()=>{suppressClick=false;},900);openTrackActions(row.dataset.trackRow,options.collectionActions);},560);});
    row.addEventListener('pointermove',event=>{if(Math.abs(event.clientX-startX)>12||Math.abs(event.clientY-startY)>12)clearHold();});
    row.addEventListener('pointerup',clearHold);row.addEventListener('pointercancel',clearHold);
    row.addEventListener('contextmenu',event=>{if(!options.collectionActions)return;event.preventDefault();openTrackActions(row.dataset.trackRow,options.collectionActions);});
    row.addEventListener('click',event=>{if(suppressClick){suppressClick=false;clearTimeout(suppressTimer);event.preventDefault();event.stopPropagation();return;}if(event.target.closest('button'))return;playTrack(row.dataset.trackRow,items);});
  });
  node.querySelectorAll('[data-track-actions]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();openTrackActions(button.dataset.trackActions,options.collectionActions);}));
  node.querySelectorAll('[data-artist]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();openArtistPage(button.dataset.artist);}));
  node.querySelectorAll('[data-like]').forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();toggleLike(btn.dataset.like);}));
  node.querySelectorAll('[data-download]').forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();downloadTrack(btn.dataset.download).catch(()=>{});}));
  node.querySelectorAll('[data-download-remove]').forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();removeDownloadedTrack(btn.dataset.downloadRemove);}));
  node.querySelectorAll('[data-remove]').forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();removeTrack(btn.dataset.remove);}));
  node.querySelectorAll('[data-playlist-remove]').forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();removeFromPlaylist(btn.dataset.playlistRemove,btn.dataset.trackId);}));
}
function renderRecentHistory(){const tracks=recentlyPlayedTracks();renderList(els['recent-history-list'],tracks);els['recent-history-list'].hidden=!tracks.length;els['recent-history-empty'].hidden=!!tracks.length;}
function renderArtistPage(){const tracks=artistTracks();const selected=state.selectedArtist||'Nghệ sĩ';els['artist-page-title'].textContent=selected;els['artist-page-count'].textContent=`${tracks.length} bài hát`;const artwork=tracks.find(track=>track.coverUrl)?.coverUrl;els['artist-page-art'].innerHTML=artwork?`<img src="${escapeHTML(artwork)}" alt="Ảnh nghệ sĩ ${escapeHTML(selected)}">`:'♫';els['artist-page-art'].classList.toggle('has-image',!!artwork);els['artist-page-play'].disabled=!tracks.length;renderList(els['artist-track-list'],tracks);els['artist-track-list'].hidden=!tracks.length;els['artist-track-empty'].hidden=!!tracks.length;}
function openArtistPage(name){state.selectedArtist=String(name||'').trim();renderArtistPage();showView('artist');}
function render(){const liked=likedTracks();const recents=recentlyPlayedTracks();const folders=[...new Set(state.tracks.map(t=>t.folder||'Nhạc của tôi'))].sort((a,b)=>a.localeCompare(b,'vi'));const downloadsFolder=state.activeFolder===DOWNLOADS_FOLDER;const offlineTracks=[...state.tracks,...state.downloads.filter(download=>!state.tracks.some(track=>track.id===download.id))];const visibleTracks=downloadsFolder?state.downloads:state.activeFolder?state.tracks.filter(t=>(t.folder||'Nhạc của tôi')===state.activeFolder):offlineTracks;if(recents.length)renderList(els['recent-list'],recents.slice(0,6));else els['recent-list'].innerHTML='<div class="empty-state compact home-recent-empty"><p>Bài bạn phát sẽ xuất hiện tại đây.</p></div>';renderList(els['liked-preview'],liked.slice(0,4));renderList(els['library-list'],visibleTracks,downloadsFolder?{downloadList:true}:{});renderList(els['liked-list'],liked,{collectionActions:{type:'liked'}});renderList(els['recommendation-list'],recommendationTracks().slice(0,4));renderRecentHistory();renderArtistPage();els['recommendation-list'].hidden=!allTracks().length;document.querySelector('.recommendation-heading').hidden=!allTracks().length;const noTracks=!allTracks().length;els['home-empty'].hidden=!noTracks;els['recent-list'].hidden=false;els['library-empty'].hidden=!!visibleTracks.length;els['library-list'].hidden=!visibleTracks.length;els['liked-empty'].hidden=!!liked.length;els['liked-list'].hidden=!liked.length;document.getElementById('liked-preview').hidden=!liked.length;document.querySelector('.liked-heading').hidden=!liked.length;const downloadedCard=`<button class="folder-card download-folder-card${downloadsFolder?' selected':''}" data-folder="${DOWNLOADS_FOLDER}"><span class="folder-card-icon">↓</span><span class="folder-card-copy"><b>Đã tải xuống</b><small>${state.downloads.length} bài hát</small></span><span class="folder-arrow">›</span></button>`;els['folder-grid'].innerHTML=[downloadedCard,...folders.map(folder=>{const count=state.tracks.filter(t=>(t.folder||'Nhạc của tôi')===folder).length;return `<button class="folder-card${state.activeFolder===folder?' selected':''}" data-folder="${escapeHTML(folder)}"><span class="folder-card-icon">♫</span><span class="folder-card-copy"><b>${escapeHTML(folder)}</b><small>${count} bài hát</small></span><span class="folder-arrow">›</span></button>`;})].join('');els['folder-grid'].hidden=!!state.activeFolder;els['folder-section-title'].textContent=downloadsFolder?'Đã tải xuống':state.activeFolder||'Thư mục nhạc';els['songs-section-title'].textContent=downloadsFolder?'Bài hát tải xuống':state.activeFolder?'Bài hát trong thư mục':'Tất cả bài hát';els['show-all-folders'].hidden=!state.activeFolder;els['library-total'].textContent=`${downloadsFolder?state.downloads.length:state.activeFolder?visibleTracks.length:offlineTracks.length} bài hát`;els['library-count'].textContent=state.tracks.length?`${state.tracks.length} bài hát`:'Chưa có bài hát';if(downloadsFolder&&!state.downloads.length){document.querySelector('#library-empty h3').textContent='Chưa có bài hát tải xuống';document.querySelector('#library-empty p').textContent='Tải bài hát trong thư viện cộng đồng hoặc tải cả danh sách phát để nghe ngoại tuyến.';document.getElementById('library-empty-import').hidden=true;}else{document.querySelector('#library-empty h3').textContent='Thư viện đang trống';document.querySelector('#library-empty p').textContent='Chọn nhạc trong điện thoại. Tệp được lưu trên thiết bị này để nghe ngoại tuyến.';document.getElementById('library-empty-import').hidden=false;}els['liked-total'].textContent=`${liked.length} bài hát`;els['liked-subtitle'].textContent=`${liked.length} bài hát`;els['liked-count'].textContent=`${liked.length} bài hát`;document.querySelectorAll('[data-folder]').forEach(button=>button.addEventListener('click',()=>{state.activeFolder=button.dataset.folder;render();}));updatePlayer();renderShared();renderSearch();renderQueue();renderPlaylists();}
function renderShared(){const tracks=state.sharedTracks;const likedIds=new Set(parseStoredArray('pink-tune-liked-shared'));tracks.forEach(t=>t.liked=likedIds.has(t.id));state.downloads.forEach(t=>t.liked=likedIds.has(t.id));if(state.communityLoading){els['community-home-heading'].hidden=false;els['community-home-list'].hidden=false;els['community-library-heading'].hidden=false;els['community-library-list'].hidden=false;els['community-empty'].hidden=true;els['community-count'].textContent='Đang tải…';for(const node of [els['community-home-list'],els['community-library-list']])node.innerHTML=Array.from({length:4},()=>'<div class="track-skeleton" aria-hidden="true"><span></span><i><b></b><b></b></i></div>').join('');return;}els['community-home-heading'].hidden=!tracks.length;els['community-home-list'].hidden=!tracks.length;els['community-library-heading'].hidden=!tracks.length;els['community-library-list'].hidden=!tracks.length;els['community-empty'].hidden=!state.supabase||!!tracks.length;els['community-count'].textContent=`${tracks.length} bài hát`;renderList(els['community-home-list'],tracks.slice(0,4));renderList(els['community-library-list'],tracks);}
function animateLike(trackId){const targets=[...document.querySelectorAll('[data-like]')].filter(button=>button.dataset.like===trackId);if(state.currentId===trackId)targets.push(els['player-like'],els['full-like']);targets.forEach(target=>{target.classList.remove('is-pop');void target.offsetWidth;target.classList.add('is-pop');setTimeout(()=>target.classList.remove('is-pop'),360);});}
async function toggleLike(trackId){const t=trackById(trackId);if(!t)return;t.liked=!t.liked;if(t.isShared){const ids=new Set(parseStoredArray('pink-tune-liked-shared'));t.liked?ids.add(t.id):ids.delete(t.id);localStorage.setItem('pink-tune-liked-shared',JSON.stringify([...ids]));if(state.downloads.some(item=>item.id===t.id))await putDownload(t);}else await putTrack(t);render();animateLike(trackId);}
async function removeTrack(trackId){const t=trackById(trackId);if(!t)return;await deleteTrack(trackId);state.tracks=state.tracks.filter(x=>x.id!==trackId);state.queue=state.queue.filter(x=>x!==trackId);if(state.currentId===trackId){audio.pause();audio.removeAttribute('src');state.currentId=null;}render();toast('Đã xóa bài hát khỏi thư viện.');}
function renderSearch(){const query=state.query.trim().toLocaleLowerCase('vi');if(!query){els['search-results'].innerHTML='<div class="empty-state compact"><div class="empty-icon">⌕</div><h3>Tìm bài hát</h3><p>Kết quả sẽ xuất hiện khi bạn nhập từ khóa.</p></div>';return;}const results=allTracks().filter(t=>`${t.title} ${t.artist}`.toLocaleLowerCase('vi').includes(query));if(!results.length){els['search-results'].innerHTML='<div class="empty-state compact"><h3>Không tìm thấy bài hát</h3><p>Thử tìm bằng tên bài hát hoặc nghệ sĩ khác.</p></div>';return;}const box=document.createElement('div');box.className='track-list full-list';els['search-results'].replaceChildren(box);renderList(box,results);}
function renderQueue(){const list=state.queue.length?state.queue:allTracks();renderList(els['queue-list'],list.map(trackById).filter(Boolean));els['queue-empty'].hidden=!!list.length;}
async function createPlaylist(title,{trackId=null,navigate=true}={}){const playlist={id:id(),title:title.trim(),ownerId:playlistOwnerId(),trackIds:trackId&&trackById(trackId)?[trackId]:[],createdAt:Date.now()};await putPlaylist(playlist);state.playlists.unshift(playlist);state.selectedPlaylistId=playlist.id;renderPlaylists();if(navigate)showView('playlists');toast(trackId?'Đã tạo danh sách và thêm bài hát.':'Đã tạo danh sách phát.');}
async function addToPlaylist(playlistId,trackId){const playlist=state.playlists.find(item=>item.id===playlistId);if(!playlist||playlist.trackIds.includes(trackId))return;playlist.trackIds.push(trackId);await putPlaylist(playlist);renderPlaylists();toast('Đã thêm bài hát vào danh sách.');}
async function removeFromPlaylist(playlistId,trackId){const playlist=state.playlists.find(item=>item.id===playlistId);if(!playlist)return;playlist.trackIds=playlist.trackIds.filter(id=>id!==trackId);await putPlaylist(playlist);renderPlaylists();}
let activeTrackAction=null;
function openTrackActions(trackId,collection){const track=trackById(trackId);if(!track||!collection)return;activeTrackAction={trackId,...collection};const playlist=state.playlists.find(item=>item.id===collection.playlistId);const collectionName=collection.type==='liked'?'Bài hát đã thích':playlist?.title||'Danh sách phát';els['track-actions-title'].textContent=track.title;els['track-actions-subtitle'].textContent=[track.artist||'Chưa rõ nghệ sĩ',collectionName].join(' · ');els['track-remove-from-list'].textContent=collection.type==='liked'?'× Bỏ khỏi bài hát đã thích':`× Xóa khỏi “${collectionName}”`;els['track-actions-main'].hidden=false;els['track-playlist-chooser'].hidden=true;els['track-action-create-form'].hidden=true;els['track-action-new-playlist-name'].value='';openDialog(els['track-actions-dialog'],'track-actions');}
function showTrackPlaylistChooser(){if(!activeTrackAction)return;const otherPlaylists=state.playlists.filter(playlist=>playlist.id!==activeTrackAction.playlistId);els['track-actions-main'].hidden=true;els['track-action-create-form'].hidden=true;els['track-playlist-chooser'].hidden=false;els['track-playlist-options'].innerHTML=`${otherPlaylists.length?otherPlaylists.map(playlist=>`<button class="track-playlist-option" type="button" data-track-target-playlist="${escapeHTML(playlist.id)}"><span class="playlist-pick-cover">♫</span><span><b>${escapeHTML(playlist.title)}</b><small>${playlist.trackIds.length} bài hát</small></span><strong>＋</strong></button>`).join(''):'<p class="muted track-playlist-empty">Chưa có danh sách khác để thêm bài.</p>'}<button class="track-playlist-option create-track-playlist-option" type="button" data-create-track-playlist>＋ Tạo danh sách mới</button>`;els['track-playlist-options'].querySelectorAll('[data-track-target-playlist]').forEach(button=>button.addEventListener('click',async()=>{const action=activeTrackAction;if(!action)return;closeDialog(els['track-actions-dialog'],'track-actions');await addToPlaylist(button.dataset.trackTargetPlaylist,action.trackId);}));els['track-playlist-options'].querySelector('[data-create-track-playlist]').addEventListener('click',()=>{els['track-playlist-chooser'].hidden=true;els['track-action-create-form'].hidden=false;els['track-action-new-playlist-name'].focus();});}
function renderLikedPicker(){const candidates=allTracks().filter(track=>!track.liked);if(!candidates.length){els['liked-add-picker'].innerHTML='<p class="muted">Không còn bài hát nào để thêm. Hãy thêm nhạc vào thư viện trước.</p>';return;}els['liked-add-picker'].innerHTML=candidates.map(track=>`<button class="playlist-pick-row" type="button" data-pick-liked="${escapeHTML(track.id)}"><span class="playlist-pick-cover">${track.coverUrl?`<img src="${escapeHTML(track.coverUrl)}" alt="" loading="lazy">`:'♫'}</span><span><b>${escapeHTML(track.title)}</b><small>${escapeHTML(track.artist)}</small></span><strong>＋</strong></button>`).join('');els['liked-add-picker'].querySelectorAll('[data-pick-liked]').forEach(button=>button.addEventListener('click',async()=>{await toggleLike(button.dataset.pickLiked);renderLikedPicker();}));}
async function deletePlaylist(playlistId){const playlist=state.playlists.find(item=>item.id===playlistId);if(!playlist)return;await deletePlaylistRecord(playlistId);state.playlists=state.playlists.filter(item=>item.id!==playlistId);state.selectedPlaylistId=null;renderPlaylists();toast('Đã xóa danh sách phát.');}
let pendingPlaylistDeletionId=null;
let playlistDeleteTimer=null;
function requestDeletePlaylist(playlistId){const playlist=state.playlists.find(item=>item.id===playlistId);if(!playlist)return;pendingPlaylistDeletionId=playlistId;let secondsRemaining=5;els['delete-playlist-name'].textContent=`Xóa danh sách “${playlist.title}”?`;els['delete-playlist-countdown'].textContent=String(secondsRemaining);els['delete-playlist-status'].textContent='Vui lòng đợi 5 giây trước khi xác nhận.';els['delete-playlist-confirm'].disabled=true;els['delete-playlist-confirm'].textContent='Đợi 5 giây…';openDialog(els['delete-playlist-dialog'],'delete-playlist');clearInterval(playlistDeleteTimer);playlistDeleteTimer=setInterval(()=>{secondsRemaining-=1;if(secondsRemaining>0){els['delete-playlist-countdown'].textContent=String(secondsRemaining);els['delete-playlist-status'].textContent=`Bạn có thể xác nhận sau ${secondsRemaining} giây.`;return;}clearInterval(playlistDeleteTimer);playlistDeleteTimer=null;els['delete-playlist-countdown'].textContent='✓';els['delete-playlist-status'].textContent='Đã hết thời gian chờ. Hãy xác nhận nếu bạn muốn xóa danh sách.';els['delete-playlist-confirm'].disabled=false;els['delete-playlist-confirm'].textContent='Xác nhận xóa danh sách';},1000);}
function clearPendingPlaylistDeletion(){clearInterval(playlistDeleteTimer);playlistDeleteTimer=null;pendingPlaylistDeletionId=null;}
function renderPlaylists(){
  if(!els['playlist-grid'])return;
  const recommendations=recommendationTracks();
  const smartCard=`<button class="playlist-card smart-playlist${state.selectedPlaylistId==='for-you'?' selected':''}" data-open-playlist="for-you"><span class="playlist-card-art smart-art">✦</span><span class="playlist-card-copy"><b>Dành cho bạn</b><small>${recommendations.length} bài · theo lượt thích và lịch sử nghe</small></span><span class="playlist-card-arrow">›</span></button>`;
  const userCards=state.playlists.map(playlist=>`<div class="playlist-card playlist-card-wrap${state.selectedPlaylistId===playlist.id?' selected':''}"><button class="playlist-card-open" type="button" data-open-playlist="${escapeHTML(playlist.id)}"><span class="playlist-card-art">♫</span><span class="playlist-card-copy"><b>${escapeHTML(playlist.title)}</b><small>${playlist.trackIds.length} bài hát</small></span><span class="playlist-card-arrow">›</span></button><details class="playlist-card-menu"><summary aria-label="Tùy chọn ${escapeHTML(playlist.title)}" title="Tùy chọn danh sách">⋮</summary><div class="playlist-card-menu-popover"><button type="button" data-play-playlist="${escapeHTML(playlist.id)}">▶ Phát danh sách</button><button type="button" data-download-playlist="${escapeHTML(playlist.id)}">↓ Tải xuống để nghe ngoại tuyến</button><button type="button" data-delete-playlist="${escapeHTML(playlist.id)}">× Xóa danh sách</button></div></details></div>`).join('');
  els['playlist-grid'].innerHTML=smartCard+userCards;
  els['playlist-grid'].querySelectorAll('[data-open-playlist]').forEach(button=>button.addEventListener('click',()=>{state.selectedPlaylistId=button.dataset.openPlaylist;renderPlaylists();}));
  els['playlist-grid'].querySelectorAll('[data-play-playlist]').forEach(button=>button.addEventListener('click',()=>{button.closest('details').open=false;playPlaylist(button.dataset.playPlaylist);}));
  els['playlist-grid'].querySelectorAll('[data-download-playlist]').forEach(button=>button.addEventListener('click',()=>{button.closest('details').open=false;downloadPlaylist(button.dataset.downloadPlaylist);}));
  els['playlist-grid'].querySelectorAll('[data-delete-playlist]').forEach(button=>button.addEventListener('click',()=>{button.closest('details').open=false;requestDeletePlaylist(button.dataset.deletePlaylist);}));
  const playlist=state.playlists.find(item=>item.id===state.selectedPlaylistId);
  const smart=state.selectedPlaylistId==='for-you';
  els['playlist-detail'].hidden=!smart&&!playlist;
  if(!smart&&!playlist)return;
  const tracks=smart?recommendations:(playlist.trackIds||[]).map(trackById).filter(Boolean);
  els['playlist-detail-heading'].textContent=smart?'Dành cho bạn':playlist.title;
  els['playlist-detail-count'].textContent=smart?'Tự chọn theo nhạc bạn thích và nghe gần đây':`${tracks.length} bài hát`;
  document.getElementById('playlist-detail-play').disabled=!tracks.length;
  document.getElementById('playlist-detail-delete').hidden=true;
  document.getElementById('playlist-add-toggle').hidden=smart;
  els['playlist-add-picker'].hidden=true;
  renderList(els['playlist-detail-list'],tracks,smart?{}:{playlistId:playlist.id,collectionActions:{type:'playlist',playlistId:playlist.id}});
  document.getElementById('playlist-detail-play').onclick=()=>tracks[0]&&playTrack(tracks[0].id,tracks);
  document.getElementById('playlist-add-toggle').onclick=()=>{const picker=els['playlist-add-picker'];picker.hidden=!picker.hidden;if(!picker.hidden)renderPlaylistPicker(playlist);};
}
function renderPlaylistPicker(playlist){const candidates=allTracks().filter(track=>!playlist.trackIds.includes(track.id));if(!candidates.length){els['playlist-add-picker'].innerHTML='<p class="muted">Không còn bài hát để thêm.</p>';return;}els['playlist-add-picker'].innerHTML=candidates.map(track=>`<button class="playlist-pick-row" data-pick-track="${escapeHTML(track.id)}"><span class="playlist-pick-cover">${track.coverUrl?`<img src="${escapeHTML(track.coverUrl)}" alt="" loading="lazy">`:'♫'}</span><span><b>${escapeHTML(track.title)}</b><small>${escapeHTML(track.artist)}</small></span><strong>＋</strong></button>`).join('');els['playlist-add-picker'].querySelectorAll('[data-pick-track]').forEach(button=>button.addEventListener('click',()=>addToPlaylist(playlist.id,button.dataset.pickTrack)));}
async function loadUserProfile(){if(!state.supabase||!state.user)return;const {data,error}=await state.supabase.from('pink_tune_profiles').select('display_name,avatar_path').eq('user_id',state.user.id).maybeSingle();if(error){console.warn('Pink Tune profile table is not ready:',error.message);state.profile={displayName:'',avatarPath:'',avatarUrl:''};return;}state.profile={displayName:data?.display_name||'',avatarPath:data?.avatar_path||'',avatarUrl:data?.avatar_path?state.supabase.storage.from(CLOUD_BUCKET).getPublicUrl(data.avatar_path).data.publicUrl:''};}
async function saveUserProfile(event){event.preventDefault();if(!state.supabase||!state.user)return;const displayName=els['profile-display-name'].value.trim();const avatarFile=els['profile-avatar-file'].files[0];if(displayName.length<2||displayName.length>60){toast('Tên hiển thị cần dài từ 2 đến 60 ký tự.');return;}if(avatarFile&&(!['image/jpeg','image/png','image/webp'].includes(avatarFile.type)||avatarFile.size>5*1024*1024)){toast('Ảnh đại diện cần là JPG, PNG hoặc WebP và tối đa 5 MB.');return;}const button=els['profile-save-button'];button.disabled=true;button.textContent='Đang lưu…';let avatarPath=state.profile.avatarPath;try{if(avatarFile){const extension={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[avatarFile.type];avatarPath=`profiles/${state.user.id}/${crypto.randomUUID()}.${extension}`;const {error}=await state.supabase.storage.from(CLOUD_BUCKET).upload(avatarPath,avatarFile,{cacheControl:'3600',upsert:false,contentType:avatarFile.type});if(error)throw error;}const {error}=await state.supabase.from('pink_tune_profiles').upsert({user_id:state.user.id,display_name:displayName,avatar_path:avatarPath||null,updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error)throw error;await loadUserProfile();renderProfile();await loadCommunityTracks();toast('Đã cập nhật trang cá nhân.');}catch(error){console.error(error);toast(`Không lưu được hồ sơ: ${error.message}. Hãy chạy migration Supabase mới.`);}finally{button.disabled=false;button.textContent='Lưu hồ sơ';}}
const CLOUD_BUCKET='pink-tune-music';
async function loadCommunityTracks(){if(!state.supabase)return;state.communityLoading=true;renderShared();let {data,error}=await state.supabase.from('pink_tune_tracks').select('id,title,artist,storage_path,cover_path,uploader_id,created_at,duration_seconds').eq('is_published',true).order('created_at',{ascending:false});let hasMediaColumns=true;if(error&&/cover_path|uploader_id|schema cache|column/i.test(error.message||'')){hasMediaColumns=false;({data,error}=await state.supabase.from('pink_tune_tracks').select('id,title,artist,storage_path,created_at,duration_seconds').eq('is_published',true).order('created_at',{ascending:false}));}state.communityLoading=false;if(error){console.error(error);els['cloud-status'].textContent='Không tải được thư viện chung. Kiểm tra cấu hình Supabase và SQL.';state.sharedTracks=[];render();return;}let profileMap=new Map();if(hasMediaColumns){const uploaderIds=[...new Set((data||[]).map(row=>row.uploader_id).filter(Boolean))];if(uploaderIds.length){const {data:profiles,error:profileError}=await state.supabase.from('pink_tune_profiles').select('user_id,display_name,avatar_path').in('user_id',uploaderIds);if(!profileError)profileMap=new Map((profiles||[]).map(profile=>[profile.user_id,profile]));}}const likedIds=new Set(parseStoredArray('pink-tune-liked-shared'));state.sharedTracks=(data||[]).map(row=>{const profile=profileMap.get(row.uploader_id);return {id:row.id,title:row.title,artist:row.artist,duration:row.duration_seconds?formatTime(row.duration_seconds):'',createdAt:row.created_at,addedAt:Date.parse(row.created_at)||Date.now(),audioUrl:state.supabase.storage.from(CLOUD_BUCKET).getPublicUrl(row.storage_path).data.publicUrl,coverUrl:row.cover_path?state.supabase.storage.from(CLOUD_BUCKET).getPublicUrl(row.cover_path).data.publicUrl:'',uploaderId:row.uploader_id||'',uploaderName:row.uploader_id?(profile?.display_name||'Người dùng Pink Tune'):'',uploaderAvatarUrl:profile?.avatar_path?state.supabase.storage.from(CLOUD_BUCKET).getPublicUrl(profile.avatar_path).data.publicUrl:'',isShared:true,liked:likedIds.has(row.id)};});render();}
function showCloudLogin(message){state.admin=false;state.canUpload=false;els['admin-login-form'].hidden=false;els['admin-upload-form'].hidden=true;els['admin-folder-link'].hidden=true;els['admin-account-create'].hidden=true;els['cloud-status'].textContent=message;}
function fetchWithTimeout(input,options={}){const controller=new AbortController();const callerSignal=options.signal;const abortFromCaller=()=>controller.abort();if(callerSignal?.aborted)controller.abort();else callerSignal?.addEventListener('abort',abortFromCaller,{once:true});const timer=setTimeout(()=>controller.abort(),8000);return fetch(input,{...options,signal:controller.signal}).finally(()=>{clearTimeout(timer);callerSignal?.removeEventListener('abort',abortFromCaller);});}
function withTimeout(promise,milliseconds,message){let timer;return Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error(message)),milliseconds);})]).finally(()=>clearTimeout(timer));}
function installAuthListener(){if(state.authListenerInstalled||!state.supabase)return;state.authListenerInstalled=true;state.supabase.auth.onAuthStateChange((event,session)=>{if(event==='INITIAL_SESSION')return;state.user=session?.user||null;state.profile={displayName:'',avatarPath:'',avatarUrl:''};state.accountReady=true;state.playHistory=parseStoredArray(historyStorageKey());setTimeout(async()=>{await Promise.all([refreshAdminPanel(),loadUserProfile(),loadCommunityTracks()]);if(state.db)await loadPlaylists();renderProfile();},0);});}
async function refreshAdminPanel(){if(!state.supabase){showCloudLogin('Chưa kết nối được Supabase. Kiểm tra kết nối Internet rồi thử lại.');els['admin-login-form'].querySelector('button[type="submit"]').disabled=true;els['cloud-retry'].hidden=false;return;}els['cloud-status'].textContent='Đang kiểm tra phiên đăng nhập…';els['cloud-retry'].hidden=true;els['admin-login-form'].querySelector('button[type="submit"]').disabled=false;try{const {data:{session}}=await withTimeout(state.supabase.auth.getSession(),9000,'Supabase phản hồi quá chậm (hơn 9 giây).');if(!session){showCloudLogin('Đăng nhập tài khoản được cấp quyền để đăng nhạc công khai.');return;}const [adminResult,uploaderResult]=await withTimeout(Promise.all([state.supabase.rpc('is_pink_tune_admin'),state.supabase.rpc('can_upload_pink_tune')]),9000,'Kiểm tra quyền tài khoản quá chậm (hơn 9 giây).');if(adminResult.error&&uploaderResult.error)throw new Error(adminResult.error.message||uploaderResult.error.message||'Không kiểm tra được quyền tài khoản.');state.admin=!adminResult.error&&adminResult.data===true;state.canUpload=state.admin||(!uploaderResult.error&&uploaderResult.data===true);els['admin-login-form'].hidden=state.canUpload;els['admin-upload-form'].hidden=!state.canUpload;els['admin-folder-link'].hidden=!state.admin;els['admin-account-create'].hidden=!state.admin;els['cloud-status'].textContent=state.admin?`Đã đăng nhập quản trị: ${session.user.email}`:state.canUpload?`Đã đăng nhập tài khoản đăng nhạc: ${session.user.email}`:'Tài khoản này chưa được cấp quyền đăng nhạc.';}catch(error){console.error('Không kiểm tra được trạng thái đăng nhập Pink Tune:',error);showCloudLogin(`Không kiểm tra được tài khoản: ${error.message||'lỗi kết nối Supabase'}. Hãy thử kết nối lại.`);els['cloud-retry'].hidden=false;}}
async function createUploaderAccount(){if(!state.supabase||!state.admin)return;const email=document.getElementById('new-uploader-email').value.trim().toLowerCase();const password=document.getElementById('new-uploader-password').value;const confirmation=document.getElementById('new-uploader-password-confirm').value;if(!/^\S+@\S+\.\S+$/.test(email)||password.length<8||password.length>128){els['cloud-status'].textContent='Nhập email hợp lệ và mật khẩu dài từ 8 đến 128 ký tự.';return;}if(password!==confirmation){els['cloud-status'].textContent='Hai mật khẩu chưa khớp.';return;}const button=els['create-uploader-button'];button.disabled=true;button.textContent='Đang tạo tài khoản…';els['cloud-status'].textContent='Đang tạo tài khoản đăng nhạc…';let result;try{result=await state.supabase.functions.invoke('admin-create-uploader',{body:{email,password}});}catch(error){result={error};}button.disabled=false;button.textContent='＋ Tạo tài khoản thường';if(result.error){let message=result.error.message||'Lỗi kết nối';try{const details=await result.error.context?.json();if(details?.error)message=details.error;}catch{}els['cloud-status'].textContent=`Không tạo được tài khoản: ${message}`;return;}document.getElementById('new-uploader-email').value='';document.getElementById('new-uploader-password').value='';document.getElementById('new-uploader-password-confirm').value='';els['cloud-status'].textContent=`Đã tạo tài khoản đăng nhạc: ${result.data.email}. Hãy gửi email và mật khẩu cho người dùng.`;}
async function initCloud(){console.log('[PinkTune] initCloud started');const config=window.PINK_TUNE_CONFIG||{};els['cloud-status'].textContent='Đang kết nối Supabase…';els['cloud-retry'].hidden=true;if(!config.supabaseUrl||!config.supabasePublishableKey){console.warn('[PinkTune] Missing supabase config',config);showCloudLogin('Thiếu cấu hình Supabase. Hãy kiểm tra tệp supabase-config.js.');els['admin-login-form'].querySelector('button[type="submit"]').disabled=true;els['cloud-retry'].hidden=false;state.accountReady=true;renderProfile();return;}if(!window.supabase?.createClient){console.warn('[PinkTune] window.supabase not available');showCloudLogin('Không tải được thư viện kết nối Supabase. Kiểm tra Internet rồi thử lại.');els['admin-login-form'].querySelector('button[type="submit"]').disabled=true;els['cloud-retry'].hidden=false;state.accountReady=true;renderProfile();return;}try{console.log('[PinkTune] Creating supabase client...');state.supabase=state.supabase||window.supabase.createClient(config.supabaseUrl,config.supabasePublishableKey,{auth:{autoRefreshToken:true,persistSession:true,detectSessionInUrl:false}});console.log('[PinkTune] Client created, installing auth listener...');installAuthListener();els['cloud-status'].textContent='Đang kiểm tra phiên đăng nhập…';console.log('[PinkTune] Getting session...');const {data:{session}}=await withTimeout(state.supabase.auth.getSession(),9000,'Supabase phản hồi quá chậm (hơn 9 giây).');console.log('[PinkTune] Session result:',session?'logged in':'no session');state.user=session?.user||null;state.accountReady=true;state.playHistory=parseStoredArray(historyStorageKey());await Promise.all([loadCommunityTracks(),refreshAdminPanel(),loadUserProfile()]);if(state.db)await loadPlaylists();renderProfile();console.log('[PinkTune] initCloud completed successfully');}catch(error){console.error('[PinkTune] initCloud failed:',error);state.accountReady=true;showCloudLogin(`Kết nối Supabase thất bại: ${error.message||'lỗi mạng'}. Hãy thử lại.`);els['admin-login-form'].querySelector('button[type="submit"]').disabled=!state.supabase;els['cloud-retry'].hidden=false;renderProfile();}}
async function uploadLargeAudio(file,storagePath){const config=window.PINK_TUNE_CONFIG;const {data:{session}}=await state.supabase.auth.getSession();if(!session)throw new Error('Phiên đăng nhập đã hết hạn. Hãy đăng nhập lại.');if(!window.tus?.Upload)throw new Error('Không tải được trình tải tệp lớn. Hãy tải lại trang.');const projectHost=new URL(config.supabaseUrl).hostname;const projectRef=projectHost.split('.')[0];return new Promise((resolve,reject)=>{const upload=new window.tus.Upload(file,{endpoint:`https://${projectRef}.storage.supabase.co/storage/v1/upload/resumable`,retryDelays:[0,3000,5000,10000,20000],headers:{authorization:`Bearer ${session.access_token}`,apikey:config.supabasePublishableKey,'x-upsert':'false'},uploadDataDuringCreation:true,removeFingerprintOnSuccess:true,metadata:{bucketName:CLOUD_BUCKET,objectName:storagePath,contentType:file.type||'application/octet-stream',cacheControl:'3600'},chunkSize:6*1024*1024,onError:reject,onProgress:(sent,total)=>{els['cloud-status'].textContent=`Đang tải lên ${Math.floor(sent/total*100)}%…`;},onSuccess:()=>resolve()});upload.findPreviousUploads().then(previous=>{if(previous.length)upload.resumeFromPreviousUpload(previous[0]);upload.start();}).catch(reject);});}
function formatUploadSize(bytes){const value=Number(bytes)||0;if(value<1024)return `${value} B`;const units=['KB','MB','GB'];const unit=Math.min(Math.floor(Math.log(value)/Math.log(1024))-1,units.length-1);return `${(value/1024**(unit+1)).toLocaleString('vi-VN',{maximumFractionDigits:1})} ${units[unit]}`;}
async function sha256Buffer(buffer){if(!crypto.subtle)throw new Error('Trình duyệt hiện tại không hỗ trợ kiểm tra tệp an toàn.');const digest=await crypto.subtle.digest('SHA-256',buffer);return Array.from(new Uint8Array(digest),byte=>byte.toString(16).padStart(2,'0')).join('');}
async function findDuplicateCommunityTracks(file){
  if(!crypto.subtle)throw new Error('Trình duyệt hiện tại không hỗ trợ kiểm tra tệp an toàn.');
  const rows=[];
  const pageSize=250;
  for(let offset=0;;offset+=pageSize){
    const {data,error}=await state.supabase.from('pink_tune_tracks').select('id,title,artist,storage_path,created_at,duration_seconds,file_size').eq('is_published',true).or(`file_size.eq.${file.size},file_size.eq.0`).order('created_at',{ascending:false}).range(offset,offset+pageSize-1);
    if(error)throw new Error(`Không truy vấn được thư viện: ${error.message}`);
    rows.push(...(data||[]));
    if(!data||data.length<pageSize)break;
  }
  if(!rows.length)return [];
  const fileHash=await sha256Buffer(await file.arrayBuffer());
  const matches=[];
  for(let index=0;index<rows.length;index++){
    const row=rows[index];
    let cached=state.communityHashes.get(row.id);
    if(!cached){
      els['cloud-status'].textContent=`Đang so sánh tệp với bài ${index+1}/${rows.length}: ${row.title}…`;
      const audioUrl=state.supabase.storage.from(CLOUD_BUCKET).getPublicUrl(row.storage_path).data.publicUrl;
      const controller=new AbortController();
      const timeout=setTimeout(()=>controller.abort(),120000);
      try{
        const response=await fetch(audioUrl,{signal:controller.signal,cache:'force-cache'});
        if(!response.ok)throw new Error(`máy chủ trả về ${response.status}`);
        const audioBytes=await response.arrayBuffer();
        cached={hash:await sha256Buffer(audioBytes),size:audioBytes.byteLength};
        state.communityHashes.set(row.id,cached);
      }catch(error){
        throw new Error(`Không thể đối chiếu bài “${row.title}”: ${error.message||'lỗi tải tệp'}`);
      }finally{clearTimeout(timeout);}
    }
    if(cached.hash===fileHash){
      const existing=state.sharedTracks.find(track=>track.id===row.id);
      matches.push({...row,actualFileSize:Number(row.file_size)||cached.size,uploaderName:existing?.uploaderName||(existing?.uploaderId?'Tài khoản Pink Tune':'Chưa có thông tin người đăng')});
    }
  }
  return matches;
}
function describeDuplicateTracks(file,matches){const dateFormat=new Intl.DateTimeFormat('vi-VN',{dateStyle:'medium',timeStyle:'short'});const details=matches.slice(0,5).map((track,index)=>{const createdAt=track.created_at?dateFormat.format(new Date(track.created_at)):'Không rõ';return `${index+1}. ${track.title} — ${track.artist||'Chưa rõ nghệ sĩ'}\n   Mã bài: ${track.id}\n   Người đăng: ${track.uploaderName}\n   Ngày đăng: ${createdAt}\n   Dung lượng: ${formatUploadSize(track.actualFileSize||track.file_size)}`;});if(matches.length>5)details.push(`… và ${matches.length-5} bản trùng khác.`);return `Tệp “${file.name}” (${formatUploadSize(file.size)}) trùng hoàn toàn với nhạc đã có (đối chiếu SHA-256). Bài mới chưa được tải lên.\n\nBài đã có trong thư viện:\n${details.join('\n\n')}`;}
async function uploadCommunityTrack(event){event.preventDefault();if(!state.supabase||!state.canUpload)return;const file=document.getElementById('shared-audio-file').files[0];const coverFile=document.getElementById('shared-cover-file').files[0];if(!file)return;if(file.size>50*1024*1024){els['cloud-status'].textContent='Tệp vượt quá giới hạn 50 MB.';return;}if(coverFile&&(!['image/jpeg','image/png','image/webp'].includes(coverFile.type)||coverFile.size>5*1024*1024)){els['cloud-status'].textContent='Ảnh bìa cần là JPG, PNG hoặc WebP và tối đa 5 MB.';return;}const title=document.getElementById('upload-title').value.trim()||titleFromFile(file.name);const artist=document.getElementById('upload-artist').value.trim();const extension=(file.name.split('.').pop()||'audio').toLowerCase().replace(/[^a-z0-9]/g,'')||'audio';const storagePath=`${crypto.randomUUID()}.${extension}`;const coverExtension=coverFile?({'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[coverFile.type]):'';const coverPath=coverFile?`covers/${crypto.randomUUID()}.${coverExtension}`:null;const button=els['upload-submit'];button.disabled=true;button.textContent='Đang kiểm tra tệp…';els['cloud-status'].textContent='Đang kiểm tra xem tệp nhạc đã có trong thư viện chưa…';let checkingDuplicates=true;const uploadFile=async(target,path)=>{if(target.size>6*1024*1024)return uploadLargeAudio(target,path);const {error}=await state.supabase.storage.from(CLOUD_BUCKET).upload(path,target,{cacheControl:'3600',upsert:false,contentType:target.type||'application/octet-stream'});if(error)throw error;};try{const duplicates=await findDuplicateCommunityTracks(file);if(duplicates.length){els['cloud-status'].textContent=describeDuplicateTracks(file,duplicates);toast(`Tệp đã trùng với “${duplicates[0].title}” — ${duplicates[0].artist||'chưa rõ nghệ sĩ'}.`,6000);return;}checkingDuplicates=false;button.textContent='Đang tải lên…';els['cloud-status'].textContent='Đang tải tệp lên thư viện chung…';try{await uploadFile(file,storagePath);if(coverFile)await uploadFile(coverFile,coverPath);}catch(error){await state.supabase.storage.from(CLOUD_BUCKET).remove([storagePath,...(coverPath?[coverPath]:[])]);throw new Error(`Tải tệp thất bại: ${error.message}`);}const {error:rowError}=await state.supabase.from('pink_tune_tracks').insert({title,artist,storage_path:storagePath,cover_path:coverPath,uploader_id:state.user.id,file_size:file.size,is_published:true});if(rowError){await state.supabase.storage.from(CLOUD_BUCKET).remove([storagePath,...(coverPath?[coverPath]:[])]);throw new Error(`Không lưu được thông tin bài hát: ${rowError.message}.`);}els['cloud-status'].textContent='Đã đăng bài hát. Mọi người có thể nghe trong thư viện chung.';document.getElementById('admin-upload-form').reset();await loadCommunityTracks();toast('Đã đăng nhạc lên Pink Tune cho mọi người.');}catch(error){console.error(error);els['cloud-status'].textContent=checkingDuplicates?`Không thể hoàn tất kiểm tra trùng lặp: ${error.message}. Tệp chưa được tải lên; hãy thử lại.`:error.message;toast(checkingDuplicates?'Chưa tải lên vì không kiểm tra được nhạc trùng.':error.message,5000);}finally{button.disabled=false;button.textContent='↑ Tải lên thư viện chung';}}

function openPicker(){fileInput.click();}
function activeView(){return document.querySelector('.view.active')?.id.replace('view-','')||'home';}
function showView(view,{pushHistory=true,scroll=true}={}){if(!document.getElementById(`view-${view}`))view='home';const previous=activeView();if(pushHistory&&view!==previous)history.pushState({pinkTune:true,view,layer:'view'},'',location.href);document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id===`view-${view}`));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='search')els['search-input'].focus({preventScroll:true});if(view==='profile')renderProfile();if(view==='recent')renderRecentHistory();if(view==='artist')renderArtistPage();if(scroll)window.scrollTo({top:0,behavior:view==='profile'?'auto':'smooth'});}
function showNowPlaying({fromHistory=false}={}){if(!state.currentId)return;if(state.playerCloseTimer){clearTimeout(state.playerCloseTimer);state.playerCloseTimer=null;}const wasHidden=els['now-playing-screen'].hidden;if(wasHidden&&!fromHistory)history.pushState({pinkTune:true,view:activeView(),overlay:'player'},'',location.href);const open=()=>{els['player-cover'].style.viewTransitionName='none';els['full-cover'].style.viewTransitionName='album-art';els['now-playing-screen'].hidden=false;els['now-playing-screen'].classList.remove('is-closing');els['now-playing-screen'].setAttribute('aria-hidden','false');updatePlayer();};if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches){if(wasHidden){els['player-cover'].style.viewTransitionName='album-art';els['full-cover'].style.viewTransitionName='none';}document.startViewTransition(open);}else open();}
function hideNowPlaying({fromHistory=false}={}){const screen=els['now-playing-screen'];if(screen.hidden||screen.classList.contains('is-closing'))return;if(!fromHistory&&history.state?.overlay==='player'){history.back();return;}screen.setAttribute('aria-hidden','true');const close=()=>{screen.hidden=true;screen.classList.remove('is-closing');els['full-cover'].style.viewTransitionName='none';els['player-cover'].style.viewTransitionName='album-art';};if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.startViewTransition(close);return;}if(matchMedia('(prefers-reduced-motion: reduce)').matches){close();return;}screen.classList.add('is-closing');state.playerCloseTimer=setTimeout(()=>{state.playerCloseTimer=null;close();},220);}
function openDialog(dialog,overlay){if(dialog.open)return;history.pushState({pinkTune:true,view:activeView(),overlay},'',location.href);dialog.showModal();}
function closeDialog(dialog,overlay,{fromHistory=false}={}){if(!dialog.open)return;if(!fromHistory&&history.state?.overlay===overlay){history.back();return;}dialog.close();}
let exitBackUntil=0;
let leavingApp=false;
function guardAppExit(){if(Date.now()<exitBackUntil){exitBackUntil=0;leavingApp=true;setTimeout(()=>history.back(),0);setTimeout(()=>{leavingApp=false;},700);return;}exitBackUntil=Date.now()+2200;toast('Nhấn nút quay lại lần nữa để thoát Pink Tune.');history.pushState({pinkTune:true,view:'home',layer:'guard'},'',location.href);}
function syncNavigation(event){
  const target=event.state;
  if(leavingApp){if(target?.pinkTune){setTimeout(()=>history.back(),0);return;}leavingApp=false;return;}
  if(els['admin-dialog'].open){els['admin-dialog'].close();return;}
  if(els['queue-dialog'].open){els['queue-dialog'].close();return;}
  if(els['create-playlist-dialog'].open){els['create-playlist-dialog'].close();return;}
  if(els['track-actions-dialog'].open){els['track-actions-dialog'].close();return;}
  if(els['delete-playlist-dialog'].open){els['delete-playlist-dialog'].close();return;}
  if(!els['now-playing-screen'].hidden&&target?.overlay!=='player'){hideNowPlaying({fromHistory:true});return;}
  if(target?.overlay==='player'){showNowPlaying({fromHistory:true});return;}
  if(!target?.pinkTune){guardAppExit();return;}
  if(target.layer==='root'&&target.view==='home'){guardAppExit();return;}
  exitBackUntil=0;showView(target.view||'home',{pushHistory:false,scroll:false});
}
function initNavigationHistory(){const saved=history.state?.pinkTune?history.state:null;const view=saved?.view||'home';history.replaceState({pinkTune:true,view,layer:'root'},'',location.href);history.pushState({pinkTune:true,view,layer:'guard'},'',location.href);showView(view,{pushHistory:false,scroll:false});window.addEventListener('popstate',syncNavigation);}

initNavigationHistory();

