const mainContent=document.querySelector('.main-content');
mainContent.addEventListener('dragover',event=>{if([...event.dataTransfer.types].includes('Files')){event.preventDefault();event.dataTransfer.dropEffect='copy';mainContent.classList.add('is-dragging');}});
